for(const [id,...names] of jobs)rows['job.'+id]=names;for(const [id,...names] of items)rows['item.'+id]=names;
export const dictionaries=Object.fromEntries(['ru','uk','en'].map((lang,i)=>[lang,Object.fromEntries(Object.entries(rows).map(([key,names])=>[key,names[i]]))]));
let language='ru';export const setLanguage=lang=>{language=['ru','uk','en'].includes(lang)?lang:'ru';};export const getLanguage=()=>language;export const t=key=>dictionaries[language][key]||dictionaries.ru[key]||key;
export const number=n=>new Intl.NumberFormat(language==='uk'?'uk-UA':language==='en'?'en-US':'ru-RU',{maximumFractionDigits:n<100?1:0}).format(n);
export function compact(n){const units=[[1e15,'Qa'],[1e12,'T'],[1e9,'B'],[1e6,'M'],[1e4,'K']];for(const [value,suffix] of units)if(n>=value)return number(n/(suffix==='K'?1000:value))+suffix;return number(n);}
export const money=n=>`${compact(n)} ₴`;
